package com.hostelmanagement.controller;
import com.hostelmanagement.repository.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.GetMapping;
@Controller public class ViewController { private final StudentRepository students; private final RoomRepository rooms; private final ComplaintRepository complaints; public ViewController(StudentRepository s,RoomRepository r,ComplaintRepository c){students=s;rooms=r;complaints=c;} @GetMapping("/") public String home(){return "redirect:/dashboard";} @GetMapping("/login") public String login(){return "login";} @GetMapping("/dashboard") public String dashboard(Model m){m.addAttribute("students",students.count());m.addAttribute("rooms",rooms.count());m.addAttribute("complaints",complaints.count());return "dashboard";} }
